            acc += a*(x[i]-acc); y[i] = acc
        return y
    a = 1.0-np.exp(-2*np.pi*np.asarray(fc)/SR)
    y = np.empty_like(x); acc = 0.0
    for i in range(len(x)):
        acc += a[i]*(x[i]-acc); y[i] = acc
    return y

