import numpy as np, wave
w=wave.open('/workspace/work/preview.wav','rb'); sr=w.getframerate()
x=np.frombuffer(w.readframes(w.getnframes()),dtype='<i2').reshape(-1,2).astype(float)/32768
def peaks(t0,dur,fmax=3000,n=8):
    s=int(t0*sr); e=s+int(dur*sr); seg=x[s:e,0]
    seg=seg*np.hanning(len(seg)); N=len(seg)*8
    X=np.abs(np.fft.rfft(seg,N)); f=np.fft.rfftfreq(N,1/sr)
    Xs=X.copy(); out=[]
    for _ in range(n):
        i=int(np.argmax(Xs)); 
        if Xs[i]<1e-4: break
        out.append((round(float(f[i]),1), round(float(20*np.log10(Xs[i]/X.max())),1)))
        a=max(0,i-30); b=min(len(Xs),i+30); Xs[a:b]=0
    return out
